function signed_gcd(a: int64, b: int64) returns int64:
    if a < 0:
        a = -a
    if b < 0:
        b = -b
    while b != 0:
        remainder = a
        while remainder >= b:
            remainder = remainder - b
        a = b
        b = remainder
    return a

