namespace benchmark

enum InventoryEvent:
    stock(sku: string, quantity: int64)
    sale(sku: string, quantity: int64)

enum InventoryResult:
    accepted(balances: map[string, int64])
    rejected(index: int64, sku: string)

function apply_inventory(events: list[InventoryEvent]) returns InventoryResult:
    let balances = map[string, int64]()
    var index = 0

    for event in events:
        match event:
            stock(sku, quantity):
                if quantity <= 0:
                    return rejected(index: index, sku: sku)
                balances.set(sku, balances.get(sku) + quantity)

            sale(sku, quantity):
                if quantity <= 0:
                    return rejected(index: index, sku: sku)

                let balance = balances.get(sku)
                if balance < quantity:
                    return rejected(index: index, sku: sku)

                balances.set(sku, balance - quantity)

        index = index + 1

    return accepted(balances: balances)

