namespace benchmark

enum Expr:
    literal(value: int64)
    add(left: Expr, right: Expr)
    divide(numerator: Expr, denominator: Expr)
    negate(inner: Expr)

enum EvalResult:
    value(number: int64)
    division_by_zero

function propagate_result(result: EvalResult) returns EvalResult:
    match result:
        value(_):
            return EvalResult.division_by_zero
        division_by_zero:
            return EvalResult.division_by_zero

function add_value(left_number: int64, right_result: EvalResult) returns EvalResult:
    match right_result:
        value(right_number):
            return EvalResult.value(number: left_number + right_number)
        division_by_zero:
            return EvalResult.division_by_zero

function add_results(left_result: EvalResult, right_result: EvalResult) returns EvalResult:
    match left_result:
        value(left_number):
            return add_value(left_number, right_result)
        division_by_zero:
            return propagate_result(right_result)

function divide_value(numerator_value: int64, denominator_result: EvalResult) returns EvalResult:
    match denominator_result:
        value(denominator_value):
            if denominator_value == 0:
                return EvalResult.division_by_zero
            return EvalResult.value(number: numerator_value / denominator_value)
        division_by_zero:
            return EvalResult.division_by_zero

function divide_results(numerator_result: EvalResult, denominator_result: EvalResult) returns EvalResult:
    match numerator_result:
        value(numerator_value):
            return divide_value(numerator_value, denominator_result)
        division_by_zero:
            return propagate_result(denominator_result)

function negate_result(result: EvalResult) returns EvalResult:
    match result:
        value(number):
            return EvalResult.value(number: -number)
        division_by_zero:
            return EvalResult.division_by_zero

function evaluate(expression: Expr) returns EvalResult:
    match expression:
        literal(value):
            return EvalResult.value(number: value)
        add(left, right):
            EvalResult left_result = evaluate(left)
            EvalResult right_result = evaluate(right)
            return add_results(left_result, right_result)
        divide(numerator, denominator):
            EvalResult numerator_result = evaluate(numerator)
            EvalResult denominator_result = evaluate(denominator)
            return divide_results(numerator_result, denominator_result)
        negate(inner):
            EvalResult inner_result = evaluate(inner)
            return negate_result(inner_result)
